import type { PostalAddressModel } from './postal-address.model';

export interface ContactModel {
  email?: string;
  phone?: string;
  postal?: PostalAddressModel;
}

import type { PersonModel } from '../contact/person.model';
import type { OrganizationAffiliationModel } from '../organization/organization-affiliation.model';

export interface DocumentContributorModel extends PersonModel {
  /**
   * 'author' | 'editor' | 'reviewer' | 'contributor'
   */
  role: string;
  affiliation?: OrganizationAffiliationModel;
}

export interface DocumentLicenseModel {
  /** ID court/normalisé : 'ISC', 'CC-BY-4.0', 'MIT', 'proprietary', 'custom' */
  id: string;

  /** Nom lisible complet */
  name: string;

  /** URL vers le texte officiel (recommandé) */
  url?: string;

  /** Texte custom si licence non-standard */
  customText?: string;
}

import type { DocumentContributorModel } from './document-contributor.model';
import type { DocumentLicenseModel } from './document-license.model';

export interface DocumentModel {
  /** Type de document */
  /**
   * 'article' | 'book' | 'standard' | 'website' | 'internal' | 'thesis'
   */
  type: string;
  title: string;
  version?: string;
  license: DocumentLicenseModel;
  contributors?: DocumentContributorModel[];

  /** Date publication (ISO 8601: "YYYY-MM-DD") */
  publicationDate: Date;

  /** Journal/revue */
  journal?: string;

  /** ISSN journal */
  issn?: string;

  /** DOI (préféré pour articles) */
  doi?: string;

  /** URL stable */
  url?: string;

  /** Volume */
  volume?: string;

  /** Numéro */
  issue?: string;

  /** Pages */
  pages?: string;

  /** Éditeur */
  publisher?: string;

  /** ID interne */
  internalId?: string;

  /** Confiance/qualité (0.0-1.0) */
  confidence?: number;

  /** Mots-clés/indexation */
  keywords?: string[];
}

import type { FeatureFormInputType } from '../types';

export interface FeatureFormInputModel {
  name: string;
  type: FeatureFormInputType;
}

export interface FeatureFormNodeModel {
  title?: string;
  description?: string;
  children?: FeatureFormNodeModel[];
}

import type { TermMetadataModel } from '../lexicon/term-metadata.model';

export interface FieldModel {
  name: TermMetadataModel['name'];
}

import type { ContactModel } from '../contact/contact.model';

export interface OrganizationAffiliationModel {
  organization: string; // TODO
  contact: ContactModel;
}

import type { OrganizationAffiliationModel } from './organization-affiliation.model';

export interface OrganizationRoleModel extends OrganizationAffiliationModel {
  department?: string; // TODO
  jobTitle: string; // TODO
}

import type { PersonNameModel } from './person-name.model';

export interface PersonModel {
  names: PersonNameModel[];
  orcid?: string;
  url?: string;
}

export interface PersonNameComponentModel {
  type: 'prefix' | 'given' | 'middle' | 'family' | 'suffix' | 'infix' | 'generation' | 'nickname';
  value: string;
}

import type { LocaleCode } from '../../../constructors/locale-code';
import type { PersonNameComponentModel } from './person-name-component.model';

export interface PersonNameModel {
  locale: LocaleCode;
  components: PersonNameComponentModel[];
}

export interface PostalAddressModel {
  street?: string;
  city?: string;
  postalCode?: string;
  region?: string;
  country?: string;
  type?: string;
}

import type { TermModel } from './term.model';
import type { DocumentModel } from '../document/document.model';

export interface TermDefinitionModel {
  name: TermModel['name'];
  locale: TermModel['locale'];
  text: string;
  reference: DocumentModel;
}

import type { Uid } from '../../../constructors/uid';

export interface TermDomainModel {
  id: Uid;
}

import type { TermModel } from './term.model';

/**
 * @computed
 */
export interface TermMetadataModel {
  readonly name: TermModel['name'];
  readonly locales: TermModel['locale'][];
  readonly tags: TermModel['tags'];
}

import type { LocaleCode } from '../../../constructors/locale-code';
import type { TermDefinitionModel } from './term-definition.model';

export interface TermModel {
  locale: LocaleCode;
  name: string;
  label: string;
  definitions: TermDefinitionModel[];
  synonyms?: TermModel[];
  tags: string[];
}

