  }

  /**
   * Generates a new UUIDv7 object from the `unixTsMs` passed, or returns
   * `undefined` upon significant timestamp rollback.
   *
   * This method is equivalent to {@link generateOrAbort} except that it takes a
   * custom timestamp and clock rollback allowance.
   *
   * @param rollbackAllowance - The amount of `unixTsMs` rollback that is
   * considered significant. A suggested value is `10_000` (milliseconds).
   * @throws RangeError if `unixTsMs` is not a 48-bit unsigned integer.
   */
  generateOrAbortCore(unixTsMs: number, rollbackAllowance: number): UUID | undefined {
    const MAX_COUNTER = 0x3ff_ffff_ffff;

    if (!Number.isInteger(unixTsMs) || unixTsMs < 0 || unixTsMs > 0xffff_ffff_ffff) {
      throw new RangeError('`unixTsMs` must be a 48-bit unsigned integer');
    } else if (rollbackAllowance < 0 || rollbackAllowance > 0xffff_ffff_ffff) {
      throw new RangeError('`rollbackAllowance` out of reasonable range');
    }

    unixTsMs++;
    if (unixTsMs > this.timestampBiased) {
      this.timestampBiased = unixTsMs;
      this.resetCounter();
    } else if (unixTsMs + rollbackAllowance >= this.timestampBiased) {
      // go on with previous timestamp if new one is not much smaller
      this.counter++;
      if (this.counter > MAX_COUNTER) {
        // increment timestamp at counter overflow
        this.timestampBiased++;
        this.resetCounter();
      }
    } else {
      // abort if clock went backwards to unbearable extent
      return undefined;
    }

    return UUID.fromFieldsV7(
      this.timestampBiased - 1,
      Math.trunc(this.counter / 2 ** 30),
      this.counter & (2 ** 30 - 1),
      this.random.nextUint32(),
    );
  }

  /** Initializes the counter at a 42-bit random integer. */
  private resetCounter(): void {
    this.counter = this.random.nextUint32() * 0x400 + (this.random.nextUint32() & 0x3ff);
  }

  /**
   * Generates a new UUIDv4 object utilizing the random number generator inside.
   *
   * @internal
   */
  generateV4(): UUID {
    const bytes = new Uint8Array(
      Uint32Array.of(
        this.random.nextUint32(),
        this.random.nextUint32(),
        this.random.nextUint32(),
        this.random.nextUint32(),
      ).buffer,
    );
    bytes[6] = 0x40 | (bytes[6] >>> 4);
    bytes[8] = 0x80 | (bytes[8] >>> 2);
    return UUID.ofInner(bytes);
  }
}

/** A global flag to force use of cryptographically strong RNG. */
declare const UUIDV7_DENY_WEAK_RNG: boolean;

/** Returns the default random number generator available in the environment. */
const getDefaultRandom = (): { nextUint32(): number } => {
  // detect Web Crypto API
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues !== 'undefined') {
    return new BufferedCryptoRandom();
  } else {
    // fall back on Math.random() unless the flag is set to true
    if (typeof UUIDV7_DENY_WEAK_RNG !== 'undefined' && UUIDV7_DENY_WEAK_RNG) {
      throw new Error('no cryptographically strong RNG available');
    }
    return {
      nextUint32: (): number => Math.trunc(Math.random() * 0x1_0000) * 0x1_0000 + Math.trunc(Math.random() * 0x1_0000),
    };
  }
};

/**
 * Wraps `crypto.getRandomValues()` to enable buffering; this uses a small
 * buffer by default to avoid both unbearable throughput decline in some
 * environments and the waste of time and space for unused values.
 */
class BufferedCryptoRandom {
  private readonly buffer = new Uint32Array(8);
  private cursor = 0xffff;
  nextUint32(): number {
    if (this.cursor >= this.buffer.length) {
      crypto.getRandomValues(this.buffer);
      this.cursor = 0;
    }
    return this.buffer[this.cursor++];
  }
}

let defaultGenerator: V7Generator | undefined;

/**
 * Generates a UUIDv7 string.
 *
 * @returns The 8-4-4-4-12 canonical hexadecimal string representation
 * ("xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx").
 */
export const uuidv7 = (): string => uuidv7obj().toString();

/** Generates a UUIDv7 object. */
export const uuidv7obj = (): UUID => (defaultGenerator || (defaultGenerator = new V7Generator())).generate();

/**
 * Generates a UUIDv4 string.
 *
 * @returns The 8-4-4-4-12 canonical hexadecimal string representation
 * ("xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx").
 */
export const uuidv4 = (): string => uuidv4obj().toString();

/** Generates a UUIDv4 object. */
export const uuidv4obj = (): UUID => (defaultGenerator || (defaultGenerator = new V7Generator())).generateV4();

