(value: unknown): Double => {
  const number = Number(value);

  if (!Number.isFinite(number)) {
    throw new TypeError('Double() expects a finite number');
  }

  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  return number as Double;
}

(value: unknown): Int => {
  const number = Number(value);

  if (!Number.isInteger(number)) {
    throw new TypeError('Int() expects an integer number');
  }

  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  return number as Int;
}

(value?: unknown): LocaleCode => {
  assert(typeof value === 'string', 'LocaleCode() expects a string');

  const [canonical] = Intl.getCanonicalLocales(value);

  assert(canonical !== undefined, 'Invalid locale');

  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  return canonical as LocaleCode;
}

(value?: unknown): Uid => {
  if (value === undefined) {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
    return uuidv7() as Uid;
  }

  if (typeof value !== 'string') {
    throw new TypeError('Uid() expects a UUID string');
  }

  const regex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;

  if (!regex.test(value)) {
    throw new TypeError('Uid() expects a valid UUID');
  }

  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  return value as Uid;
}
